```js
import { World } from './core.js'
import { defineExtension } from './extensions.js'
import { defineWorldResource } from './resources.js'

export const trapStepQueue = defineWorldResource('trap.stepQueue', {
  create: () => [],
  reset: queue => {
    queue.length = 0
